const e="Ils racontent que le ciel, les montagnes et les hommes ont tous une mémoire.",t="Récit de Tangfall",n=["Peuple & Lignée","Ancien Peuple de Tangfall","Codex #PEU-013"],s=[10,13],i="Tangto, Tangfall",a="Tradition orale, Spiritualité, Histoire ancienne",o="160cm - 185cm",l="90",c="« Singes du vent »",r="Fenghou_icone.jpeg",u="Rare",d=[{title:"Présentation",type:"text",content:"Les Fenghou sont un peuple ancestral de Tangfall. Leur culture s'est développée autour de récits sur les dieux anciens, la mémoire du monde et les cataclysmes du passé."},{title:"Les Récits de Tangfall",type:"text",content:"Leurs chroniques mentionnent la trahison d'un ancien dieu et des catastrophes cosmiques dont le Vieux Monde a perdu toute trace."},{title:"Relations continentales",type:"politique_list_long",content:[{headline:"Coexistence",title:"Les Tangto",content:"Partagent le territoire de Tangto dans une longue tradition d'échanges culturels.",color:"#34D399"},{headline:"Curiosité",title:"Les Explorateurs du Vieux Monde",content:"Leurs récits ont suscité l'intérêt des érudits menant à la Découverte de Neien.",color:"#C29B38"}]},{title:"Aujourd'hui",type:"text",content:"Ils vivent dans les régions de Tangto à Tangfall, préservant des enseignements oubliés par le reste d'Asun."}],g={citation:e,citation_author:t,tags:n,link_articles:s,class:"Ancienne / Spirituelle",repart:i,trait:a,height:o,age:l,surname:c,image:r,statut:u,sections:d};export{l as age,e as citation,t as citation_author,g as default,o as height,r as image,s as link_articles,i as repart,d as sections,u as statut,c as surname,n as tags,a as trait};
